variables.input:
timeseries n=count(`snmp.winserver.hr.systemuptime`), by:{`dt.entity.dt:snmp-winserver`, device.name}
| fields device.name
| filter isNotNull(device.name)

0.query:
timeseries u=avg(`snmp.winserver.hr.systemuptime`), by:{device.name}, filter:{in(device.name, array($ServerName))}
| fieldsAdd `Uptime days` = arrayLast(u) / 8640000
| fields device.name, `Uptime days`

1.query:
timeseries load=avg(`snmp.winserver.hr.processorload`), by:{device.name}, filter:{in(device.name, array($ServerName))}
| fieldsAdd `CPU used` = arrayLast(load)
| fields device.name, `CPU used`

3.query:
timeseries { size=avg(`snmp.winserver.hr.storagesize`), used=avg(`snmp.winserver.hr.storageused`) }, by:{device.name, storage.allocationunits}, filter:{in(device.name, array($ServerName)) AND contains(storage.descr, "Physical Memory")}
| fieldsAdd `Memory used` = arrayLast(used) / arrayLast(size) * 100
| fields device.name, `Memory used`

6.query:
timeseries { size=avg(`snmp.winserver.hr.storagesize`), used=avg(`snmp.winserver.hr.storageused`) }, by:{device.name}, filter:{in(device.name, array($ServerName)) AND contains(storage.descr, "Physical Memory")}
| fieldsAdd `Memory used %` = used[] / size[] * 100
| fields timeframe, interval, device.name, `Memory used %`

7.query:
timeseries n=count(`snmp.winserver.hr.systemuptime`), by:{device.name}, filter:{in(device.name, array($ServerName))}
| fieldsAdd Up = 100 * n[] / n[]
| fieldsRemove n

9.query:
timeseries { rx=sum(`snmp.winserver.if.in.octets.count`, rate:1s), tx=sum(`snmp.winserver.if.out.octets.count`, rate:1s) }, by:{device.name}, filter:{in(device.name, array($ServerName))}
| fieldsAdd `NIC received` = rx[] * 8 / 1000000, `NIC sent` = tx[] * 8 / 1000000
| fieldsRemove rx, tx

12.query:
timeseries { size=avg(`snmp.winserver.hr.storagesize`), used=avg(`snmp.winserver.hr.storageused`) }, by:{device.name, storage.descr, storage.allocationunits}, filter:{in(device.name, array($ServerName))}
| filter substring(storage.descr, from: 1, to: 2) == ":" and arrayLast(size) > 0
| fieldsAdd Disk = substring(storage.descr, from: 0, to: 3), alloc = toDouble(storage.allocationunits)
| summarize Disks = count(), by:{device.name}

13.query:
timeseries { size=avg(`snmp.winserver.hr.storagesize`), used=avg(`snmp.winserver.hr.storageused`) }, by:{device.name, storage.descr, storage.allocationunits}, filter:{in(device.name, array($ServerName))}
| filter substring(storage.descr, from: 1, to: 2) == ":" and arrayLast(size) > 0
| fieldsAdd Disk = substring(storage.descr, from: 0, to: 3), alloc = toDouble(storage.allocationunits)
| fieldsAdd t = arrayLast(size) * alloc / 1073741824
| summarize `Space total GiB` = sum(t), by:{device.name}

14.query:
timeseries { size=avg(`snmp.winserver.hr.storagesize`), used=avg(`snmp.winserver.hr.storageused`) }, by:{device.name, storage.descr, storage.allocationunits}, filter:{in(device.name, array($ServerName))}
| filter substring(storage.descr, from: 1, to: 2) == ":" and arrayLast(size) > 0
| fieldsAdd Disk = substring(storage.descr, from: 0, to: 3), alloc = toDouble(storage.allocationunits)
| fieldsAdd a = (arrayLast(size) - arrayLast(used)) * alloc / 1073741824
| summarize `Space available GiB` = sum(a), by:{device.name}

15.query:
timeseries { size=avg(`snmp.winserver.hr.storagesize`), used=avg(`snmp.winserver.hr.storageused`) }, by:{device.name, storage.descr, storage.allocationunits}, filter:{in(device.name, array($ServerName))}
| filter substring(storage.descr, from: 1, to: 2) == ":" and arrayLast(size) > 0
| fieldsAdd Disk = substring(storage.descr, from: 0, to: 3), alloc = toDouble(storage.allocationunits)
| fieldsAdd u = arrayLast(used) * alloc / 1073741824
| summarize `Space used GiB` = sum(u), by:{device.name}

16.query:
timeseries { size=avg(`snmp.winserver.hr.storagesize`), used=avg(`snmp.winserver.hr.storageused`) }, by:{device.name, storage.descr, storage.allocationunits}, filter:{in(device.name, array($ServerName))}
| filter substring(storage.descr, from: 1, to: 2) == ":" and arrayLast(size) > 0
| fieldsAdd Disk = substring(storage.descr, from: 0, to: 3), alloc = toDouble(storage.allocationunits)
| fieldsAdd p = arrayLast(used) / arrayLast(size) * 100
| summarize `Fullest disk %` = max(p), by:{device.name}

18.query:
timeseries st=avg(`snmp.winserver.svc.operatingstate`), by:{device.name, svc.name}, filter:{in(device.name, array($ServerName))}
| filter isNotNull(arrayLast(st))
| summarize `Running services` = count(), by:{device.name}

19.query:
timeseries st=avg(`snmp.winserver.svc.operatingstate`), by:{device.name, svc.name}, from:now()-24h, interval:5m, filter:{in(device.name, array($ServerName))}
| filter isNull(arrayLast(st))
| fields device.name, svc.name
